from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api, RmodConfig


class Rmod(BtsComponent):
    """ Represents generic Radio Module. """

    def __init__(self,
                 name: str,
                 api: Api,
                 api_alias: str,
                 ssh_ip: str,
                 rmod_init_config: RmodConfig):
        """
        :param name: name of this RMOD, unique for BTS to which it is connected; i.e. 'RMOD-1'
        :param api: API used for performing operations on this RMOD
        :param api_alias: name of opened API connection which this RMOD should use
        :param ssh_ip: IP address of this RMOD which will be used to connect via SSH
        :param rmod_init_config: configuration details, taken from init file, of this RMOD
        """
        super(Rmod, self).__init__(name)
        self._id = None
        self._serial_number = None
        self._product_code = None
        self._api = api
        self._api_alias = api_alias
        self._ssh_ip = ssh_ip
        self._rmod_init_config = rmod_init_config
        self._cells = ComponentCollection()
        self._antennas = ComponentCollection()

    def __eq__(self, other):
        return self._name == other.name

    @property
    def string_representation(self):
        info = f'      {self._name}:'

        for cell in self._cells:
            info += f'\n{cell.string_representation}'

        return info

    @property
    def id(self) -> str:
        """ Returns ID of this RMOD as it is under 'id' key in API response, i.e. '1'.  """
        return self._id

    @property
    def serial_number(self) -> str:
        """ Returns serial number of this RMOD. """
        return self._serial_number

    @property
    def product_code(self) -> str:
        """ Returns product code of this RMOD. """
        return self._product_code

    @property
    def cells(self) -> ComponentCollection:
        """ Returns all Cells configured on this RMOD. """
        return self._cells

    @property
    def antennas(self) -> ComponentCollection:
        """ Returns all Antennas from this RMOD. """
        return self._antennas

    def lock(self, timeout: int):
        """
        Locks this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.lock.__name__))

    def unlock(self, timeout: int):
        """
        Unlocks this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.unlock.__name__))

    def reset(self, timeout: int):
        """
        Resets this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which operation should be successfully completed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.reset.__name__))

    def get_power_usage(self) -> float:
        """
        Returns current power usage (in watts) of this RMOD.
        :return: current power usage (in watts) of this RMOD
        :raises ResultError: if any step of reading power usage from this RMOD fails
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.get_power_usage.__name__))

    def download_file(self, file_path: str, local_dir_path: str) -> str:
        """
        Downloads file from this RMOD to local machine.
        :param file_path: absolute path to file on RMOD which should be downloaded, i.e. '/mnt/runtime/snapshot.zip'
        :param local_dir_path: absolute path to directory on local machine where file should be downloaded, i.e. '/home/ute/Downloads'
        :return: absolute path to downloaded file on local machine, i.e. '/home/ute/Downloads/snapshot.zip'
        :raises ResultError: if any step of downloading file from this RMOD fails
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.download_file.__name__))

    def remove_file(self, file_path: str):
        """
        Removes file from this RMOD. Won't fail if file does not exist.
        :param file_path: absolute path to file on this RMOD which should be removed, i.e. '/mnt/runtime/snapshot.zip'
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.remove_file.__name__))
